#include <map>
#include <string>
#include <vector>

namespace
{
    enum class State { Unvisited, Visiting, Started, Failed };

    struct Walker
    {
        const std::map<std::string, std::vector<std::string>>& requires_;
        std::vector<std::string>& problems;
        std::map<std::string, State> state;
        std::vector<std::string> order;

        bool visit(const std::string& plugin)
        {
            State& s{ state[plugin] };
            if (s == State::Started) return true;
            if (s == State::Failed) return false;
            if (s == State::Visiting) return false;          // the caller reports the cycle
            s = State::Visiting;
            const auto it{ requires_.find(plugin) };
            for (const std::string& need : it->second)
            {
                if (!requires_.count(need)) { fail(plugin, plugin + " needs " + need); return false; }
                if (state[need] == State::Visiting || need == plugin) { fail(plugin, plugin + " is part of a cycle"); markCycle(need); return false; }
                if (!visit(need))
                {
                    if (state[plugin] == State::Failed) return false;   // already reported as part of a cycle
                    fail(plugin, plugin + " needs " + need);
                    return false;
                }
            }
            state[plugin] = State::Started;
            order.push_back(plugin);
            return true;
        }

        void fail(const std::string& plugin, const std::string& line)
        {
            if (state[plugin] == State::Failed) return;
            state[plugin] = State::Failed;
            problems.push_back(line);
        }

        void markCycle(const std::string& plugin)
        {
            if (state[plugin] == State::Visiting) fail(plugin, plugin + " is part of a cycle");
        }
    };
}

std::vector<std::string> startOrder(const std::map<std::string, std::vector<std::string>>& requires_, std::vector<std::string>& problems)
{
    Walker w{ requires_, problems, {}, {} };
    for (const auto& [plugin, needs] : requires_) w.visit(plugin);
    return w.order;
}

unitTests:
#include <algorithm>
using Needs = std::map<std::string, std::vector<std::string>>;
using Lines = std::vector<std::string>;
TEST("the example") { Lines p; CHECK_EQ(startOrder(Needs{ {"fog", {}}, {"seasons", {"fog", "weather"}}, {"weather", {}}, {"storms", {"weather", "wind"}} }, p), (Lines{ "fog", "weather", "seasons" })); CHECK_EQ(p, (Lines{ "storms needs wind" })); }
TEST("no requirements") { Lines p; CHECK_EQ(startOrder(Needs{ {"b", {}}, {"a", {}} }, p), (Lines{ "a", "b" })); CHECK(p.empty()); }
TEST("a chain") { Lines p; CHECK_EQ(startOrder(Needs{ {"a", {"b"}}, {"b", {"c"}}, {"c", {}} }, p), (Lines{ "c", "b", "a" })); }
TEST("failure spreads") { Lines p; CHECK(startOrder(Needs{ {"a", {"b"}}, {"b", {"gone"}} }, p).empty()); CHECK_EQ(p, (Lines{ "b needs gone", "a needs b" })); }
TEST("a cycle") { Lines p; const auto order = startOrder(Needs{ {"x", {"y"}}, {"y", {"x"}}, {"z", {}} }, p); CHECK_EQ(order, (Lines{ "z" })); CHECK_EQ(p.size(), std::size_t{ 2 }); CHECK(p[0].find("cycle") != std::string::npos); CHECK(p[1].find("cycle") != std::string::npos); }
TEST("requires itself") { Lines p; CHECK(startOrder(Needs{ {"me", {"me"}} }, p).empty()); CHECK_EQ(p, (Lines{ "me is part of a cycle" })); }
TEST("depends on a cycle") { Lines p; startOrder(Needs{ {"a", {"x"}}, {"x", {"y"}}, {"y", {"x"}} }, p); CHECK_EQ(p.front(), std::string("y is part of a cycle")); CHECK(std::find(p.begin(), p.end(), std::string("a needs x")) != p.end()); }

